using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWarpInteractionOperations:RefCounted
{
    private readonly ImageDocumentOperations _documents=new();private readonly ImageLayerOperations _layers=new();private readonly ImageWarpOperations _brush=new();
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var value)?value:fallback;
    private static Control Canvas(RefCounted owner)=>owner.Get("canvas").As<Control>();
    private readonly struct ProjectionContext
    {
        public readonly Transform2D World;public readonly Vector2 Content,Origin;public readonly double Zoom;private readonly Transform2D _inverse;private readonly ImageLayerProjection _projection;
        public ProjectionContext(Resource item,Transform2D world,Vector2 content,Vector2 origin,double zoom){World=world;Content=content;Origin=origin;Zoom=zoom;_inverse=world.AffineInverse();_projection=new ImageLayerProjection(item);}
        public Vector2 WorldPoint(Vector2 uv)=>World*_projection.Project(uv*Content,new Vector2(-1,-1));
        public Vector2 Screen(Vector2 uv)=>Origin+WorldPoint(uv)*(float)Zoom;
        public Vector2 LocalUv(Vector2 point)=>_projection.Unproject(_inverse*point)/Content.Max(Vector2.One);
        public Vector2 ScreenUv(Vector2 point)=>LocalUv((point-Origin)/(float)Zoom);
    }
    private ProjectionContext Context(RefCounted owner,Resource item){var canvas=Canvas(owner);return new ProjectionContext(item,_documents.world_transform(canvas.Get("document").As<Resource>(),item),_layers.content_dimensions(item),canvas.Call("origin").AsVector2(),canvas.Get("zoom").AsDouble());}
    public Settings settings(RefCounted owner)
    {
        var result=new Settings();foreach(var pair in new[]{("mode","mode"),("brush","brush"),("diameter","diameter"),("strength","strength"),("hardness","hardness"),("pressure","pressure_enabled"),("grid","show_grid"),("freeze","show_freeze"),("selection","selection_only"),("pin_radius","pin_radius"),("resolution","mesh_resolution"),("mesh_radius","mesh_radius"),("mesh_attenuation","mesh_attenuation")})result[pair.Item1]=owner.Get(pair.Item2);return result;
    }
    public void restore_settings(RefCounted owner,Settings values)
    {
        foreach(var pair in new[]{("mode","mode","brush"),("brush","brush","push")})owner.Set(pair.Item2,Get(values,pair.Item1,pair.Item3).AsString());foreach(var pair in new[]{("diameter","diameter",180.0),("strength","strength",.5),("hardness","hardness",.25),("pin_radius","pin_radius",.3),("mesh_radius","mesh_radius",.5),("mesh_attenuation","mesh_attenuation",2.0)})owner.Set(pair.Item2,Get(values,pair.Item1,pair.Item3).AsDouble());foreach(var pair in new[]{("pressure","pressure_enabled",true),("grid","show_grid",false),("freeze","show_freeze",true),("selection","selection_only",false)})owner.Set(pair.Item2,Get(values,pair.Item1,pair.Item3).AsBool());owner.Set("mesh_resolution",Get(values,"resolution",4).AsInt32());
    }
    public Resource? layer(RefCounted owner){var canvas=Canvas(owner);var document=canvas.Get("document").As<Resource>();var selected=canvas.Get("selected").AsGodotArray();return document==null||selected.Count==0?null:_documents.layer_for_id(document,selected[selected.Count-1].AsString());}
    public Vector2 local_uv(RefCounted owner,Vector2 documentPoint,Resource item)=>Context(owner,item).LocalUv(documentPoint);
    public Vector2 screen(RefCounted owner,Vector2 uv,Resource item)=>Context(owner,item).Screen(uv);
    public Resource ensure_data(RefCounted owner,Resource item)
    {
        var data=item.Get("warp").As<Resource>();if(data==null){data=new KiwiImageWarpData();item.Set("warp",data);var kernel=data.Call("_native").As<ImageWarpKernel>();kernel.initialize(data,_layers.content_dimensions(item));kernel.reset_mesh(data,owner.Get("mesh_resolution").AsInt32());}return data;
    }
    public void begin(RefCounted owner,Resource item,Vector2 uv)
    {
        var canvas=Canvas(owner);canvas.EmitSignal("gesture_started");owner.Set("active",true);owner.Set("_changed",false);owner.Set("_layer_id",item.Get("id"));var data=ensure_data(owner,item);var kernel=data.Call("_native").As<ImageWarpKernel>();var context=Context(owner,item);if(owner.Get("mode").AsString()=="brush")kernel.refine_for_brush(data,context.Content,owner.Get("diameter").AsDouble());kernel.capture_baseline(data);var selection=canvas.Get("selection").As<Image>();var restriction=Array.Empty<float>();if(owner.Get("selection_only").AsBool()){int count=data.Get("displacement").AsVector2Array().Length;restriction=new float[count];if(selection!=null){var size=data.Get("grid_size").AsVector2I();var bounds=new Rect2I(Vector2I.Zero,selection.GetSize());var bridge=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_warp_interaction.gd");bool hasWarp=bridge.Call("_has_inverse",canvas).AsBool();var mapping=canvas.Get("_selection_mapping").AsGodotObject() as ImageSelectionMapping;var inverse=canvas.Get("selection_inverse").AsTransform2D();for(int index=0;index<count;index++){var world=context.WorldPoint(new Vector2(index%size.X,index/size.X)/(Vector2)(size-Vector2I.One));var sample=hasWarp?(mapping!=null?mapping.inverse(world):bridge.Call("_selection_point",canvas,world).AsVector2()):inverse*world;var at=(Vector2I)sample.Floor();restriction[index]=bounds.HasPoint(at)?selection.GetPixelv(at).A:0;}}}data.Set("restriction",restriction);kernel.touch(data);owner.Set("_last",uv);owner.Set("_pointer",uv);owner.Set("_start",uv);canvas.Set("_drag","warp");canvas.EmitSignal("gesture_changed");
    }
    public bool handle(RefCounted owner,InputEvent input)
    {
        var canvas=Canvas(owner);var item=layer(owner);if(input is InputEventMouseMotion motion){if(canvas.Get("_drag").AsString()=="pan")return false;canvas.Set("_mouse",motion.Position);canvas.QueueRedraw();if(owner.Get("active").AsBool()&&item!=null&&item.Get("id").AsString()==owner.Get("_layer_id").AsString()){owner.Set("_pointer",Context(owner,item).ScreenUv(motion.Position));owner.Set("_pending",true);owner.Set("_pressure",owner.Get("pressure_enabled").AsBool()&&motion.Pressure>0?motion.Pressure:1.0);owner.Set("_freeze_erase",motion.CtrlPressed);}return true;}if(input is not InputEventMouseButton button)return false;canvas.Set("_mouse",button.Position);string mode=owner.Get("mode").AsString();if(button.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown){if(button.Pressed&&button.ShiftPressed){if(mode=="mesh"){double radius=owner.Get("mesh_radius").AsDouble();radius=Math.Clamp(Mathf.Snapped(radius+Math.Max(.01,radius*.12)*(button.ButtonIndex==MouseButton.WheelUp?1:-1),.01),0,2);owner.Set("mesh_radius",radius);if(owner.Get("active").AsBool()&&item!=null){owner.Set("_mesh_weights",mesh_weights(owner.Get("_original").AsVector2Array(),owner.Get("selected_points").AsInt32Array(),_layers.content_dimensions(item),radius,owner.Get("mesh_attenuation").AsDouble()));owner.Set("_pending",true);}}else owner.Set("diameter",Math.Clamp(owner.Get("diameter").AsDouble()*(button.ButtonIndex==MouseButton.WheelUp?1.1:1/1.1),2,2048));owner.EmitSignal("settings_changed");canvas.QueueRedraw();return true;}return false;}if(button.ButtonIndex==MouseButton.Middle||Input.IsKeyPressed(Key.Space))return false;if(item==null||!_documents.can_edit(canvas.Get("document").As<Resource>(),item)){if(button.Pressed)canvas.EmitSignal("hint_changed","Select an unlocked layer to warp");return true;}if(item.Get("kind").AsString()=="group"){canvas.EmitSignal("hint_changed","Use Rasterize group for warp to edit the combined artwork");return true;}var context=Context(owner,item);var uv=context.ScreenUv(button.Position);if(button.ButtonIndex==MouseButton.Right&&button.Pressed){if(owner.Get("active").AsBool()){cancel(owner);return true;}if(mode=="pins"&&item.Get("warp").AsGodotObject()!=null){int hit=HitPin(item,button.Position,context);if(hit>=0){begin(owner,item,uv);var data=item.Get("warp").AsGodotObject();data.Get("pins").AsGodotArray().RemoveAt(hit);data.Call("touch");owner.Set("_changed",true);owner.Set("selected_pin",-1);finish(owner);}}return true;}if(button.ButtonIndex!=MouseButton.Left)return false;if(!button.Pressed){finish(owner);return true;}canvas.GrabFocus();if(mode=="brush"){if(!new Rect2(Vector2.Zero,Vector2.One).Grow((float)(owner.Get("diameter").AsDouble()/Math.Max(1,context.Content.Length()))).HasPoint(uv))return true;begin(owner,item,uv);owner.Set("_pending",true);owner.Set("_freeze_erase",button.CtrlPressed);}else if(mode=="mesh"){if(!owner.Get("show_grid").AsBool())return true;int hit=HitMesh(owner,item,button.Position,context);if(hit<0)return true;var selected=new List<int>(owner.Get("selected_points").AsInt32Array());if(button.ShiftPressed){if(!selected.Remove(hit))selected.Add(hit);}else if(!selected.Contains(hit)){selected.Clear();selected.Add(hit);}owner.Set("selected_points",selected.ToArray());begin(owner,item,uv);var original=item.Get("warp").AsGodotObject().Get("mesh_points").AsVector2Array();owner.Set("_original",original);owner.Set("_mesh_weights",mesh_weights(original,selected.ToArray(),context.Content,owner.Get("mesh_radius").AsDouble(),owner.Get("mesh_attenuation").AsDouble()));}else if(mode=="pins"){int hit=HitPin(item,button.Position,context);var data=item.Get("warp").AsGodotObject();if(hit<0&&data!=null&&data.Get("pins").AsGodotArray().Count>=128){canvas.EmitSignal("hint_changed","Pin limit reached · Remove unused pins before adding more");return true;}begin(owner,item,uv);data=item.Get("warp").AsGodotObject();var pins=data.Get("pins").AsGodotArray();if(hit<0){pins.Add(new Settings{["source"]=uv,["target"]=uv,["radius"]=owner.Get("pin_radius"),["locked"]=false});hit=pins.Count-1;owner.Set("_changed",true);data.Call("touch");}owner.Set("selected_pin",hit);var pin=pins[hit].AsGodotDictionary();if(button.CtrlPressed){pin["locked"]=!Get(pin,"locked",false).AsBool();data.Call("touch");owner.Set("_changed",true);finish(owner);return true;}owner.Set("_original",new[]{pin["target"].AsVector2()});owner.EmitSignal("settings_changed");}canvas.QueueRedraw();return true;
    }
    public void process(RefCounted owner,double delta)
    {
        var canvas=Canvas(owner);if(!owner.Get("active").AsBool()||canvas.Get("_drag").AsString()=="pan")return;var item=layer(owner);if(item==null||item.Get("id").AsString()!=owner.Get("_layer_id").AsString()){cancel(owner);return;}var data=item.Get("warp").As<Resource>();string mode=owner.Get("mode").AsString();bool pending=owner.Get("_pending").AsBool();if(mode=="brush"){string kind=owner.Get("brush").AsString();if(!pending&&kind=="push")return;if(kind=="freeze"&&owner.Get("_freeze_erase").AsBool())kind="thaw";if(_brush.stroke(data,_layers.content_dimensions(item),owner.Get("_last").AsVector2(),owner.Get("_pointer").AsVector2(),owner.Get("diameter").AsDouble(),owner.Get("strength").AsDouble()*owner.Get("_pressure").AsDouble(),owner.Get("hardness").AsDouble(),kind,Math.Min(2,delta*60))){owner.Set("_changed",true);canvas.EmitSignal("gesture_changed");}owner.Set("_last",owner.Get("_pointer"));}else if(pending&&mode=="mesh"){var original=owner.Get("_original").AsVector2Array();var weights=owner.Get("_mesh_weights").AsFloat32Array();var points=new Vector2[original.Length];var movement=owner.Get("_pointer").AsVector2()-owner.Get("_start").AsVector2();for(int index=0;index<points.Length;index++)points[index]=original[index]+movement*weights[index];data.Set("mesh_points",points);data.Call("touch");owner.Set("_changed",true);canvas.EmitSignal("gesture_changed");}else if(pending&&mode=="pins"){var pins=data.Get("pins").AsGodotArray();int selected=owner.Get("selected_pin").AsInt32();if(selected>=0&&selected<pins.Count){var pin=pins[selected].AsGodotDictionary();if(!Get(pin,"locked",false).AsBool()){pin["target"]=owner.Get("_original").AsVector2Array()[0]+owner.Get("_pointer").AsVector2()-owner.Get("_start").AsVector2();data.Call("touch");owner.Set("_changed",true);canvas.EmitSignal("gesture_changed");}}}owner.Set("_pending",false);canvas.QueueRedraw();
    }
    public float[] mesh_weights(Vector2[] points,int[] selected,Vector2 extent,double radius,double attenuation)
    {
        var weights=new float[points.Length];var metric=extent/Math.Max(1,Math.Max(extent.X,extent.Y));var selectedSet=new HashSet<int>(selected);for(int index=0;index<points.Length;index++){if(selectedSet.Contains(index)){weights[index]=1;continue;}if(radius<=0)continue;double distance=double.PositiveInfinity;foreach(int seed in selected)if(seed>=0&&seed<points.Length)distance=Math.Min(distance,((points[index]-points[seed])*metric).Length());double t=Math.Clamp(1-distance/radius,0,1);weights[index]=(float)Math.Pow(t*t*(3-2*t),Math.Max(.1,attenuation));}return weights;
    }
    public void finish(RefCounted owner){if(!owner.Get("active").AsBool())return;if(owner.Get("_pending").AsBool())process(owner,1.0/60);if(!owner.Get("active").AsBool())return;owner.Set("active",false);var canvas=Canvas(owner);canvas.Set("_drag","");canvas.EmitSignal(owner.Get("_changed").AsBool()?"gesture_finished":"gesture_cancelled");canvas.QueueRedraw();}
    public void cancel(RefCounted owner){if(!owner.Get("active").AsBool())return;owner.Set("active",false);owner.Set("_pending",false);var canvas=Canvas(owner);canvas.Set("_drag","");canvas.EmitSignal("gesture_cancelled");canvas.QueueRedraw();}
    private static Vector2[] MeshPoints(Resource? data,int resolution){var points=data?.Get("mesh_points").AsVector2Array()??Array.Empty<Vector2>();if(points.Length>0)return points;points=new Vector2[resolution*resolution];for(int index=0;index<points.Length;index++)points[index]=new Vector2(index%resolution,index/resolution)/(resolution-1);return points;}
    private static int HitMesh(RefCounted owner,Resource item,Vector2 at,ProjectionContext context){var data=item.Get("warp").As<Resource>();int resolution=data!=null?data.Get("mesh_resolution").AsInt32():owner.Get("mesh_resolution").AsInt32();var points=MeshPoints(data,resolution);for(int index=0;index<points.Length;index++)if(context.Screen(points[index]).DistanceTo(at)<10)return index;return -1;}
    private static int HitPin(Resource item,Vector2 at,ProjectionContext context){var data=item.Get("warp").AsGodotObject();if(data==null)return -1;var pins=data.Get("pins").AsGodotArray();for(int index=0;index<pins.Count;index++)if(context.Screen(pins[index].AsGodotDictionary()["target"].AsVector2()).DistanceTo(at)<11)return index;return -1;}
    public int hit_mesh(RefCounted owner,Resource item,Vector2 at)=>HitMesh(owner,item,at,Context(owner,item));
    public int hit_pin(RefCounted owner,Resource item,Vector2 at)=>HitPin(item,at,Context(owner,item));
}
